/** What applying a decision option does. Every option Nexus offers is one of these; nothing else is accepted. */
export type DecisionAction =
  /**
   * Run the unit again from its history; where execution was unknown this authorizes the replay. `restart` starts it
   * over from its authorized task when its history cannot be recovered (its verification obligation is kept).
   */
  | { kind: "retry"; clearResources?: string[]; restart?: boolean }
  /** Restart the wait bound and keep waiting for the parked resources. */
  | { kind: "keep_waiting" }
  /** Run the unit on this resource, accepting the listed unmet requirements (never the trust boundary). */
  | { kind: "assign"; resourceId: string; overriding: string[] }
  /** Append the operator's note to the unit's task and run it again. */
  | { kind: "revise" }
  /** Replace the unit's task with the operator's note (the only way to shrink a prompt) and run it again. */
  | { kind: "replace_task" }
  /** Merge the operator's note, a JSON object of named strings, into the unit's `inputs` and run it again. */
  | { kind: "set_inputs" }
  /** Remove this unit's context budget and run it again (the resource limit still applies). */
  | { kind: "lift_context_budget" }
  /** Drop an advisory unit (required units cannot be dropped: the objective would be unmet). */
  | { kind: "drop" }
  | { kind: "cancel_operation" }
  | { kind: "accept_no_change" };

export interface DecisionOption {
  id: string;
  label: string;
  action: DecisionAction;
}

export type BlockCause =
  | "EXECUTION_FAILED"
  | "MERGE_CONFLICT"
  | "INTEGRATION_FAILED"
  | "CONTEXT_BUDGET"
  | "EXECUTION_UNKNOWN"
  | "INTERRUPTED"
  | "NO_QUALIFIED_RESOURCE"
  | "RESOURCE_NEEDS_OPERATOR"
  | "WAIT_BOUND"
  | "RUN_BUDGET"
  | "NOT_CONVERGING";

/** The smallest decision that unblocks progress, with the concrete options Nexus can act on. */
export interface EscalationDecision {
  id: string;
  unitId: string;
  cause: BlockCause;
  question: string;
  options: DecisionOption[];
}

export interface AppliedDecision {
  decisionId: string;
  optionId: string;
  label: string;
  action: DecisionAction;
  note?: string;
  at: string;
}

export interface WorkUnit {
  id: string;
  title: string;
  role?: AgentRole;
  prompt: string;
  dependsOn: string[];
  requires: WorkRequirements;
  /** False for advisory work: reported, run when possible, never awaited for completion. */
  required?: boolean;
  /** X-Task-Class routing hint for this unit (used when the resource has none of its own). */
  taskClass?: string;
  status: WorkUnitStatus;
  /** Resource the unit last ran on (its conversation continues from there). */
  assignment?: { resourceId: string; model: string; since: string };
  /** Operator-authorized assignment that replaces requirement matching for this unit. */
  override?: { resourceId: string; overriding: string[]; decisionId: string };
  /** Durable task state holding the unit's conversation, for resumption without live model context. */
  agentTaskId?: string;
  parked?: { since: string; reason: string; resourceIds: string[]; wakeAt?: string };
  blocked?: { since: string; reason: string; decision: EscalationDecision };
  /** A decision applied since the unit last ran, told to the unit when it resumes. */
  pendingDecision?: { label: string; note?: string; restart?: boolean };
  decisions?: AppliedDecision[];
  dropped?: boolean;
  result?: {
    summary: string;
    completedAt: string;
    resourceId: string;
    outcome: string;
    overriding?: string[];
    /** The verifier run behind the outcome, kept so dependent review units see it where nothing was integrated. */
    verification?: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false };
  };
  /**
   * The verifier run behind the unit's latest failure, present only while that failure is its last outcome: a
   * dependent failure_debugger of an isolated operation is given it as evidence while the unit waits on the operator.
   */
  failedRun?: { at: string; reason: string; summary: string; verification: { command: string; status: string; hasExecutedTests: boolean; definitionBound?: false } };
  reroutes: Array<{ at: string; from: string; to: string; reason: string }>;
  runs: number;
  /** `runs` when the operator last authorized more attempts (the run budget counts from here). */
  runsBase?: number;
  /** Executions started whose inference outcome was never received (process ended mid-run). */
  unknownResumes: number;
  modelsUsed: string[];
  /**
   * Operator cap on this unit's prompt context, in tokens. The resource's advertised capacity still applies; a unit
   * whose start prompt cannot fit this budget is blocked before any inference.
   */
  contextBudget?: number;
  /** Operator-declared paths a reviewed change may touch; a reviewer's evidence package carries it, and a diff outside it is rejected. */
  authorizedScope?: string[];
  /** Named inputs the unit's role contract requires (specialists); enforced before the unit starts. */
  inputs?: Record<string, string>;
  /** Hash of the effective inputs last submitted in this unit's conversation; a resume repeats them only on change. */
  renderedInputsHash?: string;
  /** Results the executor refused (for example a specialist output that failed its contract), most recent last. */
  rejectedOutputs?: StoredRejectedOutput[];
  /** What the unit's start prompt was estimated to need, and the budget it was checked against. */
  context?: {
    estimatedPromptTokens: number;
    budgetTokens: number;
    contextLimit: number;
    at: string;
    /** Which bound decided the check. Absent on records written before v1.1. */
    source?: "agent-estimate" | "operator-budget" | "role-ceiling";
  };
}

export type OperationEventType =
  | "RESOURCE_INELIGIBLE"
  | "RESOURCE_ELIGIBLE"
  | "WORK_STARTED"
  | "WORK_COMPLETED"
  | "WORK_REROUTED"
  | "WORK_PARKED"
  | "WORK_RESUMED"
  | "WORK_BLOCKED"
  | "CONTINUING_INDEPENDENT_WORK"
  | "OPERATION_WAITING"
  | "OPERATION_RESUMED"
  | "OPERATION_BLOCKED"
  | "OPERATION_COMPLETED"
  | "OPERATION_CANCELLED"
/**
 * Versioning and structural validation for the durable operation document.
 *
 * The operation document is the single source of truth for a durable operation. It is embedded in the task store
 * envelope, whose schema version (`CURRENT_STATE_SCHEMA_VERSION`) governs the envelope only: the envelope gate cannot
 * tell an older operation shape from a newer one. This module owns that second gate.
 *
 * Rules, in the order they are applied on load:
 *
 *   1. A record this build understands (current version) is validated and used as-is.
 *   2. A v1 record (or one that predates the field, which reads as v1) is migrated in memory by adding the schema
 *      version and nothing else. Every v1.1 field is read through a defensive default, so a migrated record keeps
 *      scheduling exactly as it did.
 *   3. A record from a newer build is refused. It is not corrupt: a build that wrote it can still read it, and
 *      quarantining it would destroy evidence. It is also never interpreted as if it were current.
 *
 * Migration is deliberately additive and lossless: the persisted record is re-serialised from the same object, so a
 * reviewer can diff a migrated record against a v1.0.0 one and see only `schemaVersion`. The store writes a
 * `.pre-migration-v1` copy of the whole record before the first v2 write (see `OperationStore.save`).
 */
import type { DurableOperationState, OperationPolicy, WorkUnit } from "./operation.js";
import { specialistInputsProblem } from "./specialist_profiles.js";
import { parseBoundaryRules } from "./boundary_rules.js";

/** The operation document version this build writes. Independent of the task-store envelope version. */
export const CURRENT_OPERATION_SCHEMA_VERSION = 2;

/** The operation document version every released 1.0.0 build wrote. */
export const LEGACY_OPERATION_SCHEMA_VERSION = 1;

/** The largest concurrency an operation may request. A cost bound, not a capacity claim. */
export const MAX_CONCURRENT_UNITS = 64;

/** A record written by a build newer than this one. Never quarantined; never interpreted. */
export class UnsupportedOperationSchemaError extends Error {
  constructor(readonly recordVersion: unknown, readonly supportedVersion = CURRENT_OPERATION_SCHEMA_VERSION) {
    super(
      `operation record schema ${String(recordVersion)} is newer than this build supports (${supportedVersion}); upgrade Nexus to open it`,
    );
    this.name = "UnsupportedOperationSchemaError";
  }
}

/** A record whose shape violates an invariant. The field and unit are named so the operator can repair the file. */
export class InvalidOperationStateError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvalidOperationStateError";
  }
}

/**
 * Brings a persisted operation document to the current version.
 *
 * Pure: the input is not mutated and no I/O happens. Throws `UnsupportedOperationSchemaError` for a newer record and
 * `InvalidOperationStateError` for a non-integer version or a failed invariant. `schemaVersion: 1` records gain the
 * version field and nothing else.
 */
export function migrateOperationState(raw: unknown): DurableOperationState {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    throw new InvalidOperationStateError("operation record is not an object");
  }
  const record = raw as Partial<DurableOperationState> & { schemaVersion?: unknown };
  const version = record.schemaVersion;
  if (version === undefined) {
    // A very old record predates the field; it has the v1 shape.
    const migrated = { ...(record as object), schemaVersion: LEGACY_OPERATION_SCHEMA_VERSION };
    return migrateOperationState(migrated);
  }
  if (typeof version !== "number" || !Number.isInteger(version) || version < 0) {
    throw new InvalidOperationStateError(`operation record has an invalid schemaVersion (${JSON.stringify(version)})`);
  }
  if (version > CURRENT_OPERATION_SCHEMA_VERSION) throw new UnsupportedOperationSchemaError(version);
  if (version < LEGACY_OPERATION_SCHEMA_VERSION) {
    throw new InvalidOperationStateError(`operation record schema ${version} is not a version this build ever wrote`);
  }
  const migrated = version === CURRENT_OPERATION_SCHEMA_VERSION ? (record as DurableOperationState) : ({ ...record, schemaVersion: CURRENT_OPERATION_SCHEMA_VERSION } as DurableOperationState);
  validateOperationState(migrated);
  return migrated;
}

/** True when the document on disk is older than this build: the store must keep a pre-migration copy before writing. */
export function needsMigrationBackup(operationSchemaVersion: unknown): boolean {
  return operationSchemaVersion !== CURRENT_OPERATION_SCHEMA_VERSION;
}

/** The effective concurrency for a state: an unset policy is the v1.0.0 behaviour, one unit at a time. */
export function effectiveConcurrency(state: Pick<DurableOperationState, "policy">): number {
  return state.policy?.maxConcurrentUnits ?? 1;
}

/**
 * Structural invariants that a scheduler or the store would otherwise trip over later, reported at load instead.
 * These are cheap checks, deliberately not a full schema: they catch the failures that would otherwise surface as a
 * confusing crash mid-run from a hand-edited or truncated file.
 */
export function validateOperationState(state: DurableOperationState): void {
  if (!Array.isArray(state.units)) throw new InvalidOperationStateError("operation record has no units array");
  for (const field of ["resources", "conditions", "events"] as const) {
    if (!Array.isArray(state[field])) throw new InvalidOperationStateError(`operation ${state.id}: ${field} is not an array`);
  }
  if (!state.policy || typeof state.policy !== "object" || Array.isArray(state.policy)) {
    throw new InvalidOperationStateError(`operation ${state.id}: policy is not an object`);
  }

  // A damaged boundary declaration is refused, not skipped: skipping it would silently switch the check off.
  if (state.boundaries !== undefined) {
    try {
      parseBoundaryRules(state.boundaries);
    } catch (error) {
      throw new InvalidOperationStateError(`operation ${state.id}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  const ids = new Set<string>();
  for (const unit of state.units) {
    if (!unit || typeof unit !== "object") throw new InvalidOperationStateError(`operation ${state.id}: a work unit is not an object`);
    if (typeof unit.id !== "string" || !unit.id) throw new InvalidOperationStateError(`operation ${state.id}: a work unit has no id`);
    if (ids.has(unit.id)) throw new InvalidOperationStateError(`operation ${state.id}: duplicate work unit id '${unit.id}'`);
    ids.add(unit.id);
    if (unit.contextBudget !== undefined && (!Number.isInteger(unit.contextBudget) || unit.contextBudget <= 0)) {
      throw new InvalidOperationStateError(`operation ${state.id}: unit '${unit.id}' has an invalid contextBudget (${String(unit.contextBudget)}); expected a positive integer`);
    }
    if (unit.inputs !== undefined) {
      const problem = specialistInputsProblem(unit.inputs);
      if (problem) throw new InvalidOperationStateError(`operation ${state.id}: unit '${unit.id}': ${problem}`);
    }
  }
  for (const unit of state.units) {
    for (const dependency of unit.dependsOn ?? []) {
      if (!ids.has(dependency)) {
        throw new InvalidOperationStateError(`operation ${state.id}: unit '${unit.id}' depends on unknown unit '${dependency}'`);
      }
    }
  }
  validateConcurrency(state.id, "policy.maxConcurrentUnits", state.policy.maxConcurrentUnits);
  for (const resource of state.resources ?? []) {
    validateConcurrency(state.id, `resource '${resource.id}'.maxConcurrentUnits`, resource.maxConcurrentUnits);
  }
  if (state.messages !== undefined) {
    if (!Array.isArray(state.messages)) throw new InvalidOperationStateError(`operation ${state.id}: messages is not an array`);
    for (const message of state.messages) {
      if (
        !message ||
        typeof message.id !== "string" ||
        typeof message.at !== "string" ||
        typeof message.kind !== "string" ||
        typeof message.body !== "string" ||
        typeof message.from !== "string" ||
        typeof message.to !== "string"
      ) {
        throw new InvalidOperationStateError(`operation ${state.id}: a message is missing its id, at, kind, from, to or body`);
      }
    }
  }
  if (state.messageSeq !== undefined && (!Number.isInteger(state.messageSeq) || state.messageSeq < 0)) {
    throw new InvalidOperationStateError(`operation ${state.id}: messageSeq must be a non-negative integer (got ${String(state.messageSeq)})`);
  }
  if (state.integrations !== undefined) {
    if (!Array.isArray(state.integrations)) throw new InvalidOperationStateError(`operation ${state.id}: integrations is not an array`);
    for (const receipt of state.integrations) {
      if (!receipt || typeof receipt.unitId !== "string" || typeof receipt.integratedCommit !== "string") {
        throw new InvalidOperationStateError(`operation ${state.id}: an integration receipt is missing its unitId or integratedCommit`);
      }
    }
  }
}

function validateConcurrency(operationId: string, field: string, value: unknown): void {
  if (value === undefined) return;
  if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > MAX_CONCURRENT_UNITS) {
    throw new InvalidOperationStateError(
      `operation ${operationId}: ${field} must be an integer from 1 to ${MAX_CONCURRENT_UNITS} (got ${String(value)})`,
    );
  }
}

/** The policy field this build adds; kept here so the scheduler and the loader agree on the default and the bound. */
export function validateOperationPolicy(policy: Partial<OperationPolicy>): void {
  validateConcurrency("(new)", "policy.maxConcurrentUnits", policy.maxConcurrentUnits);
}

/**
 * Concurrent units must not share a worktree: without `git.isolate` two units would write the same checkout.
 * Returns the operator-facing problem, or undefined when the combination is safe.
 */
export function concurrencyIsolationProblem(maxConcurrentUnits: number | undefined, isolated: boolean): string | undefined {
  if (isolated || maxConcurrentUnits === undefined || maxConcurrentUnits <= 1) return undefined;
  return `policy.maxConcurrentUnits is ${maxConcurrentUnits}, but without git.isolate concurrent units would share one worktree; set "git": { "isolate": true } or run with maxConcurrentUnits 1`;
}

/**
 * A record created before the isolation rule (or hand-edited) may ask for concurrency without isolation. It is not
 * refused, which would strand it: its limit is clamped to 1 and the returned warning names the fix.
 */
export function clampUnisolatedConcurrency(state: Pick<DurableOperationState, "policy" | "git">): string | undefined {
  const problem = concurrencyIsolationProblem(state.policy?.maxConcurrentUnits, Boolean(state.git?.isolate));
  if (!problem) return undefined;
  const limit = state.policy.maxConcurrentUnits;
  state.policy.maxConcurrentUnits = 1;
  return `${problem}; running this operation with maxConcurrentUnits 1 (was ${limit})`;
}

/**
 * Resource slots, validated wherever a resource enters the record. A value out of range must be refused at the door:
 * discovering it at load would make an operation that was accepted once permanently unreadable.
 */
export function validateResourceSlots(resources: Array<{ id?: string; maxConcurrentUnits?: unknown }>): void {
  for (const resource of resources) {
    validateConcurrency("(new)", `resource '${resource.id ?? "?"}'.maxConcurrentUnits`, resource.maxConcurrentUnits);
  }
}

/** Units whose resource is busy are still runnable; a unit that is dropped or complete is not. */
export function isSchedulable(unit: Pick<WorkUnit, "status" | "dropped">): boolean {
  return !unit.dropped && (unit.status === "RUNNABLE" || unit.status === "RUNNING");
}
/**
 * Pure convergence scheduling over durable operation state. OperationRunner owns time, execution and persistence.
 */
import type {
  AppliedDecision,
  Assignment,
  BlockSpec,
  Decision,
  DecisionAction,
  DecisionOption,
  DurableOperationState,
  EscalationDecision,
  OperationEvent,
  OperationEventType,
  OptionSpec,
  UnitRunResult,
  WorkUnit,
  WorkUnitStatus,
} from "./operation.js";
import { MAX_REJECTED_OUTPUT_CHARS, MAX_REJECTED_OUTPUTS, unitBaseTask } from "./operation.js";
import { specialistInputsProblem } from "./specialist_profiles.js";
import { redactForPersistence } from "./persistence_protection.js";
import type { ResourceDescriptor, ResourceRegistry, Selection } from "./resources.js";
import { reportOperationDiagnostic, type OperationDiagnosticHandler } from "./operation_runner_diagnostics.js";
import { effectiveConcurrency } from "./operation_schema.js";

/** Separates a unit's original task from operator revisions appended to it. */
export const REVISION_MARKER = "\n\nOperator revision: ";
const MAX_EVENTS = 300;
const TERMINAL: WorkUnitStatus[] = ["COMPLETE", "BLOCKED"];

function clockTime(ms: number): string {
  return new Date(ms).toISOString().slice(11, 16) + " UTC";
}

/** An operator decision Nexus will not apply (stale, not offered, or outside the unit's authority). */
export class DecisionRejected extends Error {}

export const isRequired = (u: Pick<WorkUnit, "required">): boolean => u.required !== false;

/**
 * Whether `dependency` is finished input for `u`: COMPLETE, or, for a failure_debugger in an isolated operation only,
 * BLOCKED on a run whose verifier did not pass. The failure is that role's input, so waiting for the dependency to
 * complete would wait for the evidence to disappear; a retried dependency is unfinished input again. Only an isolated
 * operation gives the debugger a snapshot of the failed candidate: elsewhere it would run in the shared workspace on
 * top of the blocked unit's uncommitted candidate, so it keeps waiting.
 */
function dependencySatisfied(u: WorkUnit, dependency: WorkUnit, isolated: boolean): boolean {
  if (dependency.status === "COMPLETE") return true;
  return isolated && u.role === "failure_debugger" && dependency.status === "BLOCKED" && dependency.failedRun !== undefined;
}

export class ConvergenceScheduler {
  constructor(
    readonly state: DurableOperationState,
    readonly registry: ResourceRegistry,
    private readonly now: () => number,
    private readonly onEvent?: (e: OperationEvent) => void,
    private readonly onDiagnostic?: OperationDiagnosticHandler,
  ) {}

  /** Last truncation signature reported, so repeated decide() calls do not flood the event ring. */
  private concurrencyNotice?: string;

  unit(id: string): WorkUnit {
    const u = this.state.units.find((x) => x.id === id);
    if (!u) throw new Error(`Unknown work unit ${id}`);
    return u;
  }

  emit(type: OperationEventType, message: string, extra: Omit<OperationEvent, "type" | "at" | "message"> = {}): void {
    const event: OperationEvent = { type, at: new Date(this.now()).toISOString(), message, ...extra };
    this.state.events.push(event);
    if (this.state.events.length > MAX_EVENTS) this.state.events.splice(0, this.state.events.length - MAX_EVENTS);
    try {
      this.onEvent?.(event);
    } catch {
      reportOperationDiagnostic(this.onDiagnostic, "scheduler", "event_callback_failed");
    }
  }

  private excludedModels(u: WorkUnit): Set<string> {
    return new Set((u.requires.independentOf ?? []).flatMap((id) => this.unit(id).modelsUsed));
  }

  /**
   * Re-derives every non-terminal unit's status from dependencies and resource eligibility, then chooses the next
   * transition. Called after every change (completion, resource condition, wake), never acting on stale state.
   */
  decide(): Decision {
    const now = this.now();
    if (this.state.status === "CANCELLED") return { kind: "blocked", decisions: [] };
    const previous = new Map(this.state.units.map((u) => [u.id, u.status]));
    // The whole selection is kept, not just the preferred resource: a unit whose preferred resource is reserved by
    // an earlier assignment in the same batch may use its next qualified, eligible resource instead of waiting.
    const choices = new Map<string, Selection>();
    const reroutes = new Map<string, { resourceId: string; reason: string }>();
    // The same fact OperationRunner uses to create its OperationGit: only then is there a snapshot worktree.
    const isolated = Boolean(this.state.git?.isolate);

    for (const u of this.state.units) {
      if (TERMINAL.includes(u.status) || u.status === "RUNNING") continue;
      const deps = u.dependsOn.map((d) => this.unit(d));
      if (deps.some((d) => !dependencySatisfied(u, d, isolated))) {
        u.status = "WAITING_ON_DEPENDENCY";
        delete u.parked;
        continue;
      }
      const sel = u.override ? this.overrideSelection(u, now) : this.registry.select(u.requires, this.excludedModels(u), now);
      if (sel.chosen) {
        u.status = "RUNNABLE";
        const from = u.assignment?.resourceId;
        let reroutedFrom: { resourceId: string; reason: string } | undefined;
        if (from && from !== sel.chosen.id) {
          const prior = this.registry.get(from);
          const elig = prior ? this.registry.eligibility(prior, now) : undefined;
          const reason = !prior
            ? "previous resource is no longer configured"
            : u.override?.resourceId === sel.chosen.id
              ? `operator assigned ${sel.chosen.id}`
              : elig && !elig.eligible
                ? elig.blocking.map((b) => b.reason).join("; ")
                : `${sel.chosen.id} is the preferred qualified resource`;
          reroutedFrom = { resourceId: from, reason };
        }
        choices.set(u.id, sel);
        if (reroutedFrom) reroutes.set(u.id, reroutedFrom);
        continue;
      }
      const temporary = sel.qualified.filter((c) => !c.eligibility.permanent && c.eligibility.eligibleAt !== undefined);
      if (temporary.length) {
        const wakeAt = Math.min(...temporary.map((c) => c.eligibility.eligibleAt!));
        const reason = temporary
          .map((c) => `${c.resource.id} ${c.eligibility.blocking.map((b) => b.reason).join(", ")}`)
          .join("; ");
        const wasParked = u.status === "PARKED";
        u.status = "PARKED";
        u.parked = {
          since: wasParked && u.parked ? u.parked.since : new Date(now).toISOString(),
          reason,
          resourceIds: temporary.map((c) => c.resource.id),
          wakeAt: new Date(wakeAt).toISOString(),
        };
        continue;
      }
      this.block(u, this.noQualifiedResource(u, sel));
    }

    for (const u of this.state.units) {
      const before = previous.get(u.id);
      if (u.status === "PARKED" && before !== "PARKED") {
        const others = this.productiveOthers(u.id, choices);
        this.emit(
          "WORK_PARKED",
          `${u.title} parked: ${u.parked!.reason}; eligible again ${clockTime(Date.parse(u.parked!.wakeAt!))}.` +
            (others ? ` Continuing ${others} independent ${others === 1 ? "task" : "tasks"}.` : ""),
          { unitId: u.id, detail: { parked: u.parked } },
        );
      }
    }

    // Required work first; advisory work runs when it can but never ahead of the objective.
    const runnable = this.state.units.filter((u) => u.status === "RUNNABLE" && choices.has(u.id));
    const ordered = this.orderRunnable(runnable);
    const assignments = this.assign(ordered, choices, reroutes);
    if (assignments.length) {
      const limit = effectiveConcurrency(this.state);
      const running = this.state.units.filter((u) => u.status === "RUNNING").length;
      if (ordered.length > assignments.length && running + assignments.length >= limit) {
        // One notice per distinct truncation, not one per decide() call: the scheduler is called repeatedly over the
        // same state and the event ring holds 300 entries for the whole operation.
        const signature = `${limit}|${running}|${ordered.map((u) => u.id).join(",")}`;
        if (this.concurrencyNotice !== signature) {
          this.concurrencyNotice = signature;
          this.emit(
            "CONCURRENCY_LIMIT",
            `${ordered.length} units are runnable; starting ${assignments.length} (limit ${limit}).`,
            { detail: { limit, eligible: ordered.length } },
          );
        }
      }
      return { kind: "run", assignments };
    }

    // Every runnable unit's qualified slots are held by work already in flight: nothing can start now, and the batch
    // that holds them will re-enter decide() when it settles. This is not a block and not a wait on a resource window.
    if (assignments.length === 0 && this.state.units.some((u) => u.status === "RUNNING")) {
      return {
        kind: "wait",
        wakeAt: now + this.state.policy.minWaitMs,
        reason: "every runnable unit's qualified resource is busy",
        parked: [],
      };
    }

    if (this.state.units.filter(isRequired).every((u) => u.status === "COMPLETE")) return { kind: "complete" };

    const parked = this.state.units.filter((u) => u.status === "PARKED");
    // Parked advisory work is never awaited, so it cannot postpone the decision a blocked required unit needs.
    const decisionOutstanding = this.state.units.some((u) => isRequired(u) && u.status === "BLOCKED" && u.blocked);
/**
 * Resource eligibility: which inference resources (provider × endpoint × model, optionally a serving pool) may be
 * given new work now, and when ineligible ones are expected back.
 *
 * Conditions are recorded at the narrowest scope the evidence supports. A 429 on one model does not make another
 * model ineligible; a refused connection makes the endpoint ineligible, not the provider; a quota or credential
 * failure applies to the account. Provider-specific metadata (reset headers, catalog capabilities, aihost error
 * codes) refines the picture but plain OpenAI-compatible semantics are sufficient.
 */
import { createOperationAccountIdentity, type OperationAccountIdentity } from "./account_identity.js";
import { classifyDestination, type DestinationTrustBoundary } from "./egress.js";
import { backoffDelayMs, type RecoveryPolicy } from "./provider_recovery.js";
import type { InferenceFailure } from "./turn.js";

export type ResourceCondition =
  | "AVAILABLE"
  | "TEMPORARILY_UNAVAILABLE"
  | "RATE_LIMITED"
  | "OVERLOADED"
  | "DRAINING"
  | "DEGRADED"
  | "AUTH_FAILED"
  | "PERMANENTLY_UNAVAILABLE"
  | "UNKNOWN";

export type ConditionScope = "model" | "endpoint" | "provider" | "account" | "pool";

/** A configured inference resource. Secrets are never stored here; `apiKeyEnv` names where to read one. */
export interface ResourceDescriptor {
  id: string;
  /** Provider identity; defaults to the endpoint origin. */
  provider: string;
  endpoint: string;
  model: string;
  /** Serving pool shared with other models, when known (e.g. from a gateway catalog). */
  pool?: string;
  /** Credential identity label (a fingerprint, never the secret). */
  account?: string;
  /** Distinguishes caller-provided account labels from credential-derived legacy hashes during migration. */
  accountIdentitySource?: "explicit" | "credential";
  apiKeyEnv?: string;
  /** Cloud provider id (providers.ts); the endpoint is then that provider's base URL and its key its own. */
  providerId?: string;
  capabilities: string[];
  /** Roles/task classes this resource is qualified for; undefined qualifies it for any. */
  qualifications?: string[];
  /** Qualifications this resource is the preferred choice for; it outranks resources merely qualified for them. */
  preferredFor?: string[];
  contextLength?: number;
  /** Lower is preferred. */
  rank?: number;
  /** Operator knowledge of how the provider scopes rate limits; default "model". */
  rateLimitScope?: "model" | "account" | "provider";
  /** X-Task-Class routing hint sent with requests. */
  taskClass?: string;
  /**
   * Units this resource may serve at once. Absent means 1: a resource is a single inference slot until the operator
   * says otherwise. Bounded by `MAX_CONCURRENT_UNITS`; see `operation_schema.ts`.
   */
  maxConcurrentUnits?: number;
}

export interface ResourceConditionRecord {
  scope: ConditionScope;
  key: string;
  condition: ResourceCondition;
  temporary: boolean;
  /** Provider-given time the resource may be used again (Retry-After / reset headers). */
  eligibleAt?: string;
  /** Without a provider-given time: when to try again (bounded backoff). */
  recheckAt?: string;
  source: "retry-after" | "rate-limit-reset" | "backoff" | "provider-catalog" | "probe";
  confidence: "authoritative" | "derived";
  reason: string;
  observedAt: string;
  failures: number;
  resourceId: string;
  requestId?: string;
  httpStatus?: number;
  /** Recorded for later quota-aware scheduling; not used for decisions yet. */
  quota?: { remainingRequests?: number; remainingTokens?: number };
}

export interface Eligibility {
  eligible: boolean;
  /** Earliest time the resource is expected to become eligible; undefined when permanent. */
  eligibleAt?: number;
  permanent: boolean;
  blocking: ResourceConditionRecord[];
}

export interface WorkRequirements {
  capabilities?: string[];
  qualification?: string;
  minContext?: number;
  /** Units whose resources this unit's resource must not share a model with (independent review). */
  independentOf?: string[];
  /** Least trusted destination the unit's context may be sent to. */
  minTrust?: DestinationTrustBoundary;
}

export interface Candidate {
  resource: ResourceDescriptor;
  eligibility: Eligibility;
}

export interface Selection {
  chosen?: ResourceDescriptor;
  /** Qualified resources, eligible or not. */
  qualified: Candidate[];
  /** Why each unqualified resource was rejected. */
  rejected: Array<{ resourceId: string; reasons: string[] }>;
}

/** Scheduler-side recheck backoff for unavailability without a provider-given time. */
export const RECHECK_POLICY: RecoveryPolicy = {
  deadlineMs: 0,
  baseDelayMs: 5_000,
  maxDelayMs: 10 * 60_000,
  jitterRatio: 0.2,
  minDelayMs: 1_000,
  probeTimeoutMs: 5_000,
  maxUnknownReplays: 0,
  maxIterations: 0,
};

const TRUST_RANK: Record<DestinationTrustBoundary, number> = { HOST_LOCAL: 4, LOCAL_APPLIANCE: 3, EXTERNAL_BOUNDED: 2, EXTERNAL_PUBLIC: 1 };
const ACCOUNT_CODES = new Set(["insufficient_quota", "quota_exceeded", "billing_hard_limit_reached"]);
const POOL_CODES = new Set(["capacity_exhausted", "pool_unavailable"]);

export function credentialFingerprint(secret: string | undefined, identity: OperationAccountIdentity): string | undefined {
  return identity.fingerprint(secret);
}

export function scopeKey(resource: ResourceDescriptor, scope: ConditionScope): string | undefined {
  switch (scope) {
    case "model":
      return `${resource.provider}|model|${resource.model}`;
    case "endpoint":
      return `endpoint|${resource.endpoint}`;
    case "provider":
      return `provider|${resource.provider}`;
    case "account":
      return `${resource.provider}|account|${resource.account ?? "default"}`;
    case "pool":
      return resource.pool ? `${resource.provider}|pool|${resource.pool}` : undefined;
  }
}

