     1	/** Batch specifications deliberately use the existing `nexus operation` JSON format. */
     2	import { validateOperationSpec } from "./operation_cli.js";
     3	import { newOperation, type OperationPolicy, type WorkUnitSpec } from "./core/operation.js";
     4	import type { ResourceDescriptor } from "./core/resources.js";
     5	import type { BoundaryRules } from "./core/boundary_rules.js";
     6	
     7	export interface BatchSpecification {
     8	  id?: string;
     9	  objective: string;
    10	  units: WorkUnitSpec[];
    11	  resources?: Array<Partial<ResourceDescriptor> & { id: string; model: string; endpoint?: string }>;
    12	  discoverCatalog?: boolean;
    13	  policy?: Partial<OperationPolicy>;
    14	  git?: { isolate?: boolean; baseRef?: string };
    15	  boundaries?: BoundaryRules;
    16	}
    17	
    18	/**
    19	 * Validates an untrusted batch document using the operation parser and constructor. The constructor owns work-unit
    20	 * invariants such as dependency existence, required/advisory edges, scope normalization and cycle detection; keeping
    21	 * this path on those functions prevents `/batch` from growing a second workflow schema or DAG implementation.
    22	 */
    23	export function validateBatchSpec(spec: unknown): BatchSpecification {
    24	  validateOperationSpec(spec);
    25	  const batch = spec as BatchSpecification;
    26	  // A resource list is provider configuration and is validated by validateOperationSpec; an empty list here keeps
    27	  // validation independent of the current provider and does not perform discovery or inference.
    28	  newOperation(batch.id ?? "batch-validation", batch.objective, batch.units, [], 0, batch.policy);
    29	  return batch;
    30	}
