/**
 * /team: an orchestration strategy over the convergence foundation.
 *
 * A team is a durable operation whose work units are roles with real dependencies. Every role runs through the same
 * lower path as any scheduled unit — a truthful agent turn with provider recovery and context admission, on a
 * resource chosen by qualification and eligibility, with durable state, replay safety and cancellation — and the
 * team is COMPLETE only when every required role is COMPLETE. A role whose turn did not establish a result is
 * BLOCKED on a decision, never reported as done.
 */
import { randomUUID } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { SecurityManager } from "./security.js";
import { inputPathProtection } from "./core/specialist_inputs.js";
import { redactForPersistence } from "./core/persistence_protection.js";
import { isRequired, newOperation, type DurableOperationState, type OperationEvent, type WorkUnit, type WorkUnitSpec } from "./core/operation.js";
import { AgentWorkUnitExecutor, driveOperation, OperationStore, resourcesFromConfig, type WorkUnitExecutor } from "./core/operation_runner.js";
import type { RecoveryClock } from "./core/provider_recovery.js";
import type { ResourceDescriptor } from "./core/resources.js";
import { ROLE_PROFILES, ROLE_REQUIREMENTS, roleRequirements, SPECIALIST_CONTRACTS, isSpecialistRole, parseLeadingSpecialistInputs, type AgentRole } from "./core/roles.js";
import { mergeOperationPolicy } from "./config.js";
import type { HarnessConfig } from "./types.js";

export { ROLE_PROFILES, ROLE_REQUIREMENTS, type AgentRole, type TeamRole, type RoleProfile } from "./core/roles.js";

export const TEAM_ROLES: AgentRole[] = ["researcher", "architect", "implementer", "tester", "reviewer"];

/** Every role `/team` accepts as a single-role target: the five team roles and the specialist roles. */
export const TEAM_TARGET_ROLES: AgentRole[] = [...TEAM_ROLES, ...(Object.keys(SPECIALIST_CONTRACTS) as AgentRole[])];

export type TeamTarget = AgentRole | "full";

const UNIT_ID: Partial<Record<AgentRole, string>> = { researcher: "research", architect: "design", implementer: "implement", tester: "verify", reviewer: "review" };

/** Role turns segment at 15 steps (durable checkpoint boundary; continues until completion, stagnation or cancel unless --no-continuation is set). */
const ROLE_MAX_STEPS = 15;

/**
 * The work graph for a team target. The full workflow's chain is a genuine data dependency (design needs the
 * research, implementation needs the design, verification needs the implementation). Independent review needs only
 * the implementation, so it runs alongside verification, and must use a model the implementation did not use.
 */
export function teamUnits(target: TeamTarget, objective: string, opts: { independentReview?: boolean; workspace?: string } = {}): WorkUnitSpec[] {
  const unit = (role: AgentRole, dependsOn: string[], independentOf?: string[]): WorkUnitSpec => {
    // A specialist target takes its contract inputs as leading name=value words; they are enforced at admission.
    const parsed = isSpecialistRole(role) ? parseLeadingSpecialistInputs(role, objective) : undefined;
    return {
    id: UNIT_ID[role] ?? role,
    title: ROLE_PROFILES[role].title,
    role,
    prompt: parsed ? parsed.task : objective,
    ...(parsed && (Object.keys(parsed.inputs).length || Object.keys(parsed.files).length)
      ? { inputs: { ...parsed.inputs, ...(Object.keys(parsed.files).length ? readTeamFileInputs(requireWorkspace(opts.workspace), parsed.files) : {}) } }
      : {}),
    dependsOn,
    requires: roleRequirements(role, independentOf ? { independentOf } : {}),
    ...(ROLE_REQUIREMENTS[role].taskClass ? { taskClass: ROLE_REQUIREMENTS[role].taskClass } : {}),
    };
  };
  if (target !== "full") return [unit(target, [])];
  const units = [unit("researcher", []), unit("architect", ["research"]), unit("implementer", ["design"]), unit("tester", ["implement"])];
  if (opts.independentReview) units.push(unit("reviewer", ["implement"], ["implement"]));
  return units;
}

function requireWorkspace(workspace: string | undefined): string {
  if (!workspace) throw new Error("@file: inputs need a workspace");
  return workspace;
}

/** Largest file a `/team name=@file:path` input reads; the text is persisted with the operation. */
const MAX_TEAM_FILE_INPUT_BYTES = 64 * 1024;

/**
 * Reads the `@file:` inputs of a `/team` specialist target. The file must be a regular file inside the workspace and
 * not protected by the same security policy the read_file tool applies (checked on the path as written and on where
 * it really points, so a symlink cannot reach a protected file). The text is capped and credential-redacted before it
 * is persisted with the operation.
 */
function readTeamFileInputs(workspace: string, files: Record<string, string>): Record<string, string> {
  const root = fs.realpathSync(workspace);
  const security = new SecurityManager(root);
  const out: Record<string, string> = {};
  for (const [name, written] of Object.entries(files)) {
    const file = path.resolve(root, written);
    let real: string;
    try {
      real = fs.realpathSync(file);
    } catch {
      throw new Error(`Input '${name}': file '${written}' not found`);
    }
    if (real !== root && !real.startsWith(root + path.sep)) throw new Error(`Input '${name}': '${written}' is outside the workspace`);
    for (const candidate of [path.relative(root, file), path.relative(root, real)]) {
      const protection = inputPathProtection(security, candidate);
      if (protection) throw new Error(`Input '${name}': '${written}' is protected (${protection})`);
    }
    const stat = fs.statSync(real);
    if (!stat.isFile() || stat.size > MAX_TEAM_FILE_INPUT_BYTES) throw new Error(`Input '${name}': '${written}' is not a regular file of at most ${MAX_TEAM_FILE_INPUT_BYTES} bytes`);
    out[name] = redactForPersistence(fs.readFileSync(real, "utf8"));
  }
  return out;
}

export interface TeamRunOptions {
  signal?: AbortSignal;
  onEvent?: (e: OperationEvent) => void;
  /** Add an independent reviewer to the full workflow. */
  independentReview?: boolean;
  /** Interactive callers: waits longer than this return a durable WAITING team instead of blocking the prompt. */
  maxInProcessWaitMs?: number;
  /** Defaults: the workspace operation store, config-derived resources, agent-turn executor, real clock. */
  store?: OperationStore;
  resources?: ResourceDescriptor[];
  executor?: WorkUnitExecutor;
  clock?: RecoveryClock;
  id?: string;
}

export interface TeamOutcome {
  operation: DurableOperationState;
  /** True only when the operation is COMPLETE: every required role established its result. */
  success: boolean;
  report: string;
}

export class TeamOrchestrator {
  constructor(
    private readonly config: HarnessConfig,
    private readonly opts: TeamRunOptions = {},
  ) {}

  plan(target: TeamTarget, objective: string): DurableOperationState {
    const now = this.opts.clock?.now() ?? Date.now();
    const resources = this.opts.resources ?? resourcesFromConfig(this.config);
    const policy = mergeOperationPolicy(this.config.operationPolicy, undefined);
    return newOperation(this.opts.id ?? `team-${randomUUID().slice(0, 8)}`, objective, teamUnits(target, objective, { ...this.opts, workspace: this.config.workspace }), resources, now, policy);
  }

  async run(target: TeamTarget, objective: string): Promise<TeamOutcome> {
    return this.drive(this.plan(target, objective));
  }

  async drive(state: DurableOperationState): Promise<TeamOutcome> {
    const store = this.opts.store ?? new OperationStore(this.config.workspace);
    const executor =
      this.opts.executor ?? new AgentWorkUnitExecutor({ baseConfig: { ...this.config, maxSteps: Math.min(this.config.maxSteps, ROLE_MAX_STEPS) } });
    const operation = await driveOperation(state, {
      store,
      executor,
      signal: this.opts.signal,
      workspace: this.config.workspace,
      ...(this.opts.clock ? { clock: this.opts.clock } : {}),
      ...(this.opts.onEvent ? { onEvent: this.opts.onEvent } : {}),
      ...(this.opts.maxInProcessWaitMs !== undefined ? { maxInProcessWaitMs: this.opts.maxInProcessWaitMs } : {}),
    });
}

async function tdd({ host, args, signal }: SlashContext): Promise<SlashOutcome> {
  const issue = args.trim();
  if (!issue) return reply("tdd", "Usage: /tdd <issue description>", false);
  const agent = host.app.getAgent();
  const result = await agent.getSynthesizer().runAutonomousTdd(agent, issue, undefined, { signal, onConfirm: host.confirm(signal) });
  return result.success
    ? reply("tdd", "TDD cycle completed: RED → GREEN → REFACTOR verified.")
    : reply("tdd", `TDD cycle ended at ${result.finalPhase}: ${result.summary}`, false);
}

async function team({ host, args, signal }: SlashContext): Promise<SlashOutcome> {
  const [role, rest] = firstWord(args);
  const independentReview = /^--independent-review\b/.test(rest);
  const objective = rest.replace(/^--independent-review\b\s*/, "").trim();
  if (!role || !objective) return reply("team", TEAM_USAGE, false);
  const name = role.toLowerCase();
  if (name !== "full" && !ROLES.includes(name)) return reply("team", `Unknown role ${role}. Roles: ${[...ROLES, "full"].join(", ")}`, false);
  const events: OperationEvent[] = [];
  const orchestrator = new TeamOrchestrator(host.app.getConfig(), {
    signal,
    independentReview,
    maxInProcessWaitMs: TEAM_INTERACTIVE_WAIT_MS,
    onEvent: (e) => events.push(e),
  });
  const result = await orchestrator.run(name === "full" ? "full" : (name as AgentRole), objective);
  const log = events.map((e) => `◆ ${e.message}`);
  return reply("team", [...log, "", result.report].join("\n").trim(), result.success);
}

async function recover({ host, args }: SlashContext): Promise<SlashOutcome> {
  const result = await host.app.executeSlashCommand("recover", args);
  return reply("recover", result.output, result.success);
}

async function bang({ host, args }: SlashContext): Promise<SlashOutcome> {
  const line = args.trim();
  if (!line) return reply("!", "Usage: !<shell command> or !<history number>", false);
  if (/^\d+$/.test(line)) return recall(host.history(), line, "!");
  const receipt = await host.app.executeOperatorCommand(line);
  const parts = [receipt.output ?? "", receipt.error ?? ""].map((text) => text.trimEnd()).filter(Boolean);
  if (!receipt.success && receipt.status === "DENIED") parts.push("Execution denied by the authority admission gate.");
  return reply("!", parts.join("\n") || (receipt.success ? "(no output)" : "Command failed."), receipt.success);
}

