 480	pub fn run_live(spec: SidecarSpec) -> Result<(), Box<dyn std::error::Error>> {
 481	    install_stop_signals();
 482	    spawn_stop_watchdog();
 483	    let guard = TerminalGuard;
 484	    let depth = crate::theme::Depth::from_env();
 485	    crate::theme::apply_backend_policy(depth);
 486	    // `try_init` enters raw mode and the alternate screen and installs ratatui's restoring panic hook; its terminal
 487	    // writes plain stdout, so it is replaced by one whose writer turns 256-colour SGR into 16-colour SGR when needed.
 488	    drop(ratatui::try_init()?);
 489	    let mut terminal = LiveTerminal::new(ratatui::backend::CrosstermBackend::new(crate::theme::SgrWriter::new(
 490	        io::stdout(),
 491	        depth == crate::theme::Depth::Ansi16,
 492	    )))?;
 493	    let previous_hook = std::panic::take_hook();
 494	    std::panic::set_hook(Box::new(move |info| {
 495	        if std::thread::current().name() == Some("main") {
 496	            restore_input_modes();
 497	        }
 498	        previous_hook(info);
 499	    }));
 500	    // Each flag is set before its sequence is written, so a write that fails halfway is still undone.
 501	    PASTE_ON.store(true, Ordering::SeqCst);
 502	    execute!(io::stdout(), EnableBracketedPaste)?;
 503	    // Lets Shift+Enter arrive as its own key on terminals that speak the kitty keyboard protocol. Terminals that do
 504	    // not answer the query (tmux without extended keys, most others) send it as a plain Enter, so it is not advertised.
 505	    let shift_enter = terminal::supports_keyboard_enhancement().unwrap_or(false);
 506	    if shift_enter {
 507	        KEYBOARD_ON.store(true, Ordering::SeqCst);
 508	        execute!(
 509	            io::stdout(),
 510	            PushKeyboardEnhancementFlags(KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES)
 511	        )?;
 512	    }
 513	    let mouse = mouse_enabled(std::env::var("NEXUS_TUI_MOUSE").ok().as_deref());
 514	    if mouse {
 515	        MOUSE_ON.store(true, Ordering::SeqCst);
 516	        enable_mouse()?;
 517	    }
 518	    let mut app = LiveApp::start(spec);
 519	    app.state.depth = depth;
 520	    app.state.shift_enter = shift_enter;
 521	    app.state.mouse = mouse;
 522	    app.state.osc52 = osc52_enabled(std::env::var("NEXUS_OSC52").ok().as_deref());
 523	    let result = event_loop(&mut terminal, &mut app);
 524	    // The sidecar shutdown can take seconds: reports arriving meanwhile would reach the shell as text.
 525	    end_session(restore_input_modes, drain_terminal_input, || {
 526	        app.handle(Action::Quit);
 527	    });
 528	    drop(terminal);
 529	    drop(guard);
 530	    if let Some(breadcrumb) = maybe_format_exit_breadcrumb(&app.state) {
 531	        println!("{breadcrumb}");
 532	    }
 533	    result
 534	}
