    fn rgb(color: Color) -> (u8, u8, u8) {
        match color {
            Color::Rgb(r, g, b) => (r, g, b),
            Color::Indexed(i) => {
                const CUBE: [u8; 6] = [0, 95, 135, 175, 215, 255];
                match i {
                    16..=231 => {
                        let i = i - 16;
                        (CUBE[(i / 36) as usize], CUBE[((i / 6) % 6) as usize], CUBE[(i % 6) as usize])
                    }
                    232..=255 => {
                        let v = 8 + 10 * (i - 232);
                        (v, v, v)
                    }
                    _ => panic!("not a 256-colour entry"),
                }
            }
            other => panic!("no RGB for {other:?}"),
        }
    }

