        .unwrap_or(area.height)
        .min(area.height);
    let top = area.y + area.height.saturating_sub(height) / 2;
    frame.render_widget(paragraph, Rect::new(area.x, top, area.width, height));
}

/// What the transcript frame drew, for `LiveLayout`.
struct TranscriptFrame {
    /// Largest useful `scroll_back` (`usize::MAX` when the walk stopped before the first entry).
    limit: usize,
    /// The `scroll_back` drawn.
    back: usize,
    /// The row at the top of the window, counted from the start of its line (see `LiveState::anchor`).
    top: Option<(usize, usize, usize)>,
    /// Set when the window was kept on `LiveState::anchor`: the `scroll_back` that took.
    anchored: Option<usize>,
    /// The entry each row of the area shows, top to bottom (a row past the last entry has none).
    row_entries: Vec<usize>,
}

/// Renders the transcript window `scroll_back` rows above the newest line, with the selected entry highlighted.
/// With `follow`, the window first moves the least distance that shows the whole selected entry above the bottom row
/// (its top when it is taller than the window). While scrolled back, the window stays on the row it showed at its
/// top (`LiveState::anchor`) as entries arrive or grow below it, so reading is never interrupted by a scroll jump.
/// Only the entries needed to fill the window are laid out, so the cost follows the window, not the transcript.
/// The exception is the anchored entry while scrolled back: it is laid out once per frame and wrapped from the
/// anchored line to its end to find the distance to the bottom, so that frame costs O(that entry plus the entries below it).
fn render_transcript(frame: &mut Frame, area: Rect, state: &LiveState) -> TranscriptFrame {
    let transcript = &state.transcript;
    let selected = state.selected.filter(|_| state.focus == Focus::Transcript);
    let height = usize::from(area.height);
    let pal = diff_view::palette(state.depth);
    let selected_reviewable = selected.filter(|&i| transcript.get(i).is_some_and(Entry::reviewable));
    let lines_of = |index: usize| -> Vec<Line<'_>> {
        let review_hint = if selected == Some(index) {
            "enter to review"
        } else if selected_reviewable.is_none() && state.last_reviewable == Some(index) {
            "ctrl+d to review"
        } else {
            "tab, [ ] to select, enter to review"
        };
        entry_lines(
            &transcript[index],
            &EntryContext {
                first: index == 0,
                width: area.width,
                selected: selected == Some(index),
                after_card: index > 0 && transcript[index - 1].card().is_some(),
                review_hint,
                pal: &pal,
                streaming: state.session.busy && index + 1 == transcript.len() && matches!(transcript[index], Entry::Assistant { .. }),
                now: state.now,
            },
        )
    };
    let rows_of = |lines: &[Line<'_>]| lines.iter().map(|line| wrapped_rows(line, area.width)).sum::<usize>();
    let mut back = state.scroll_back;
    let mut anchored = None;
    // The anchored entry's lines, laid out once for the anchor and reused by the walk below.
    let mut anchor_lines: Option<(usize, Vec<Line<'_>>)> = None;
    let mut target = selected.filter(|_| state.follow);
    if back > 0
        && target.is_none()
        && let Some((entry, line_index, row_in_line)) = state.anchor
        && entry < transcript.len()
    {
        let below: usize = (entry + 1..transcript.len()).map(|i| rows_of(&lines_of(i))).sum();
        // Rows from the anchored row to the end of the entry as it is now. The anchor counts from the start of the
        // line, so an entry that grows below it (a streaming answer) lengthens this and the window stays put.
        let lines = lines_of(entry);
        let line_index = line_index.min(lines.len().saturating_sub(1));
        let from_line: usize = lines[line_index..].iter().map(|line| wrapped_rows(line, area.width)).sum();
        let in_line = lines.get(line_index).map_or(0, |line| wrapped_rows(line, area.width));
        let row_in_line = row_in_line.min(in_line.saturating_sub(1));
        back = (from_line.saturating_sub(row_in_line) + below).saturating_sub(height);
        anchor_lines = Some((entry, lines));
        anchored = Some(back);
    }
    // Walked from the newest line up: (line, its rows, entry index, the line's index in its entry, rows from the
    // bottom through it).
    let mut tail = Vec::new();
    let mut total: usize = 0;
    let mut reached_top = true;
    'entries: for index in (0..transcript.len()).rev() {
        let below = total;
        let entry_lines = match anchor_lines.take() {
            Some((anchored_entry, lines)) if anchored_entry == index => lines,
            other => {
                anchor_lines = other;
                lines_of(index)
            }
        };
        for (line_index, line) in entry_lines.into_iter().enumerate().rev() {
            let rows = wrapped_rows(&line, area.width);
            total = total.saturating_add(rows);
            tail.push((line, rows, index, line_index, total));
            if target.is_none() && total >= height.saturating_add(back) {
                reached_top = false;
                break 'entries;
            }
        }
        if target == Some(index) {
            // One row short of the bottom, where the scroll badge would cover the entry.
            back = back
                .min(below.saturating_sub(1))
                .max(total.saturating_sub(height));
            target = None;
            if total >= height.saturating_add(back) {
                reached_top = false;
                break;
            }
        }
    }
    let limit = if reached_top {
        total.saturating_sub(height)
    } else {
        usize::MAX
    };
    let back = back.min(limit);
    let first_row = total.saturating_sub(height.saturating_add(back));
    let reach = height.saturating_add(back);
    let top = tail
        .iter()
        .find(|(.., to_bottom)| *to_bottom >= reach)
        .map(|(_, _, index, line_index, to_bottom)| (*index, *line_index, to_bottom - reach));
    tail.reverse();
    let mut row_entries = Vec::with_capacity(height);
    let mut hidden = first_row;
    for (_, rows, index, ..) in &tail {
        let above = hidden.min(*rows);
        hidden -= above;
        let room = height.saturating_sub(row_entries.len());
        row_entries.extend(std::iter::repeat_n(*index, (rows - above).min(room)));
    }
    let mut skipped = 0;
    let mut covered = 0;
    let mut lines = Vec::new();
    for (line, rows, ..) in tail {
        if lines.is_empty() && skipped + rows <= first_row {
            skipped += rows;
            continue;
        }
        if covered >= height + (first_row - skipped) {
            break;
        }
        covered += rows;
        lines.push(line);
    }
    let offset = u16::try_from(first_row - skipped).unwrap_or(u16::MAX);
    frame.render_widget(
        Paragraph::new(lines)
            .wrap(Wrap { trim: false })
            .scroll((offset, 0)),
        area,
    );
    if back > 0 {
        render_scroll_badge(frame, area, back, state.unseen);
    }
    TranscriptFrame { limit, back, top, anchored, row_entries }
}

fn render_scroll_badge(frame: &mut Frame, area: Rect, rows_below: usize, unseen: bool) {
    // The longest wording that fits half the width, so the badge never hides a whole row of the transcript.
    let variants = if unseen {
        [
            format!(" ↓ new output · {rows_below} rows below · pgdn · ctrl+end newest "),
            " ↓ new output · pgdn · ctrl+end ".to_string(),
            " ↓ new · pgdn ".to_string(),
        ]
    } else {
        [
            format!(" ↓ {rows_below} more rows · pgdn · ctrl+end newest "),
            format!(" ↓ {rows_below} more rows · pgdn "),
            format!(" ↓ {rows_below} "),
        ]
    };
    let half = usize::from(area.width / 2).max(8);
    let text = variants.iter().find(|v| v.chars().count() <= half).unwrap_or(&variants[2]).clone();
    let width = u16::try_from(text.chars().count())
        .unwrap_or(area.width)
        .min(area.width);
    let at = Rect::new(area.right() - width, area.bottom() - 1, width, 1);
    frame.render_widget(
        Paragraph::new(Span::styled(
            text,
            Style::default().fg(Color::Black).bg(ACCENT),
        )),
        at,
    );
}

fn wrapped_rows(line: &Line<'_>, width: u16) -> usize {
    Paragraph::new(line.clone())
        .wrap(Wrap { trim: false })
        .line_count(width)
}

fn expand_tabs(row: &str) -> Cow<'_, str> {
    if row.contains('\t') {
        Cow::Owned(row.replace('\t', "    "))
    } else {
        Cow::Borrowed(row)
    }
}

fn one_line(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// How one transcript entry is drawn: its place and the frame it is drawn into.
struct EntryContext<'a> {
    first: bool,
    width: u16,
    selected: bool,
    /// The entry before it is an edit card (a plain tool row then opens with a blank row, so cards stay separated).
    after_card: bool,
    /// The control that opens this entry's complete diff, as the omission line names it.
    review_hint: &'a str,
    pal: &'a Palette,
    /// The entry is the reply still streaming (unclosed formatting on its last line is hidden).

output.text:
    match state.overlay {
        Overlay::None => {}
        Overlay::Detail => render_detail(frame, data, state),
        Overlay::Help => render_help(frame, data, state),
        Overlay::Validation => render_validation(frame, data, state),
    }
}

fn render_header(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot) {
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(1), Constraint::Length(1)])
        .split(area);
    let status_color = match data.status.as_str() {
        "VERIFIED" | "COMPLETE" | "NO CHANGES" | "IDLE" => Color::Green,
        "UNVERIFIED" | "STOPPING" | "BLOCKED" | "LIMIT_REACHED" | "INCOMPLETE" => Color::Yellow,
        "FAILED" | "INTERRUPTED" | "NEEDS ATTENTION" => Color::Red,
        _ => theme_accent(&data.theme),
    };
    let mut top_spans = vec![
        Span::styled(
            " NEXUS ",
            Style::default()
                .fg(Color::Black)
                .bg(theme_accent(&data.theme))
                .add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            "  WORKSPACE  ",
            Style::default().fg(MUTED).add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            short_path(&data.workspace, if area.width < 82 { 16 } else { 28 }),
            Style::default().fg(Color::Reset),
        ),
    ];
    if area.width >= 82 {
        top_spans.extend([
            Span::raw("   "),
            Span::styled(one_line(&data.model, 20), Style::default().fg(MUTED)),
        ]);
    }
    top_spans.extend([
        Span::raw("   "),
        Span::styled(
            one_line(&data.status, (area.width / 3) as usize),
            Style::default()
                .fg(status_color)
                .add_modifier(Modifier::BOLD),
        ),
    ]);
    let top = Line::from(top_spans);
    frame.render_widget(
        Paragraph::new(top).style(Style::default().bg(SURFACE)),
        rows[0],
    );
    frame.render_widget(
        Paragraph::new(Line::from(vec![
            Span::styled(
                " OBJECTIVE  ",
                Style::default()
                    .fg(theme_accent(&data.theme))
                    .add_modifier(Modifier::BOLD),
            ),
            Span::styled(
                one_line(&data.objective, area.width.saturating_sub(14) as usize),
                Style::default().fg(Color::Reset),
            ),
        ])),
        rows[1],
    );
}

fn render_activity(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot, state: &mut AppState) {
    let items = if data.activity.is_empty() {
        vec![ListItem::new(Line::from(Span::styled(
            "No work recorded yet. Start with a prompt in the REPL.",
            Style::default().fg(MUTED),
        )))]
    } else {
        data.activity
            .iter()
            .enumerate()
            .map(|(index, event)| {
                let (glyph, color) = match event.kind.as_str() {
                    "finding" => ("✳", Color::Yellow),
                    "failure" => ("×", Color::Red),
                    "warning" => ("!", Color::Yellow),
                    "change" => ("▸", theme_accent(&data.theme)),
                    "tool" => ("·", MUTED),
                    _ => ("◦", Color::Reset),
                };
                let marker = if index == state.selected { "›" } else { " " };
                ListItem::new(vec![
                    Line::from(vec![
                        Span::styled(
                            format!("{marker} {glyph} "),
                            Style::default().fg(color).add_modifier(Modifier::BOLD),
                        ),
                        Span::styled(
                            &event.title,
                            Style::default()
                                .fg(Color::Reset)
                                .add_modifier(Modifier::BOLD),
                        ),
                    ]),
                    Line::from(Span::styled(
                        format!(
                            "    {}",
                            one_line(&event.summary, area.width.saturating_sub(8) as usize)
                        ),
                        Style::default().fg(MUTED),
                    )),
                ])
            })
            .collect()
    };
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::LEFT)
                .border_style(Style::default().fg(MUTED))
                .title(Span::styled(
                    "  RECENT SIGNAL  ",
                    Style::default()
                        .fg(theme_accent(&data.theme))
                        .add_modifier(Modifier::BOLD),
                )),
        )
        .highlight_style(Style::default().add_modifier(Modifier::REVERSED));
    let mut list_state =
        ListState::default().with_selected((!data.activity.is_empty()).then_some(state.selected));
    frame.render_stateful_widget(list, area, &mut list_state);
}

fn render_context(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot) {
    if area.height <= 6 {
        let validation = data
            .validation
            .as_ref()
            .map(|receipt| receipt.status.as_str())
            .unwrap_or("Not verified");
        let active = data
            .plan
            .iter()
            .find(|item| item.status == "in_progress")
            .map(|item| item.name.as_str())
            .unwrap_or("No active milestone");
        let compact = Text::from(vec![
            Line::from(vec![
                Span::styled(
                    "VALIDATION  ",
                    Style::default()
                        .fg(theme_accent(&data.theme))
                        .add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    validation,
                    Style::default().fg(if validation == "PASSED" {
                        Color::Green
                    } else {
                        Color::Yellow
                    }),
                ),
            ]),
            Line::from(vec![
                Span::styled(
                    "PLAN  ",
                    Style::default().fg(ACCENT).add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    one_line(active, area.width.saturating_sub(8) as usize),
                    Style::default().fg(Color::Reset),
                ),
            ]),
        ]);
        frame.render_widget(Paragraph::new(compact).wrap(Wrap { trim: true }), area);
        return;
    }
    let mut lines = vec![Line::from(Span::styled(
        "  VALIDATION",
        Style::default()
            .fg(theme_accent(&data.theme))
            .add_modifier(Modifier::BOLD),
    ))];
    if let Some(validation) = &data.validation {
        let color = if validation.status == "PASSED" {
            Color::Green
        } else {
            Color::Red
        };
        lines.push(Line::from(Span::styled(
            format!("  {}", validation.status),
            Style::default().fg(color).add_modifier(Modifier::BOLD),
        )));
        if let Some(id) = &validation.candidate_id {
            lines.push(Line::from(Span::styled(
                format!("  Candidate {}", short_path(id, 18)),
                Style::default().fg(MUTED),
            )));
        }
    } else {
        lines.push(Line::from(Span::styled(
            "  Not verified",
            Style::default().fg(MUTED),
        )));
    }
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled(
        "  PLAN",
        Style::default()
            .fg(theme_accent(&data.theme))
            .add_modifier(Modifier::BOLD),
    )));
    if data.plan.is_empty() {
        lines.push(Line::from(Span::styled(
            "  No milestones",
            Style::default().fg(MUTED),
        )));
    } else {
        for item in data
            .plan
            .iter()
            .rev()
            .take(5)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
        {
            let (glyph, color) = match item.status.as_str() {
                "completed" => ("✓", Color::Green),
                "in_progress" => ("●", theme_accent(&data.theme)),
                _ => ("○", MUTED),
            };
            lines.push(Line::from(vec![
                Span::styled(format!("  {glyph} "), Style::default().fg(color)),
                Span::styled(
                    one_line(&item.name, area.width.saturating_sub(8) as usize),
                    Style::default().fg(Color::Reset),
                ),
            ]));
        }
    }
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled(
        "  CONTEXT",
        Style::default()
            .fg(theme_accent(&data.theme))
            .add_modifier(Modifier::BOLD),
    )));
    lines.push(Line::from(Span::styled(
        format!("  {}", data.context),
        Style::default().fg(MUTED),
    )));
    lines.push(Line::from(Span::styled(
        format!("  Task {}", short_path(&data.task_id, 18)),
        Style::default().fg(MUTED),
    )));
    frame.render_widget(
        Paragraph::new(Text::from(lines)).wrap(Wrap { trim: true }),
        area,
    );
}

fn render_footer(frame: &mut ratatui::Frame, area: Rect, data: &Snapshot) {
    let text = if area.width < 90 {
        "↑↓ move · enter inspect · ? help · q return".to_string()
    } else {
        let validation_key = if data.validation.is_some() {
            "   v validation"
        } else {
            ""
        };
        format!(
            " ↑↓ navigate   enter detail   ? help{validation_key}                         q return to REPL "
        )
    };
    frame.render_widget(
        Paragraph::new(text).style(Style::default().fg(MUTED).bg(SURFACE)),
        area,
    );
}

fn render_detail(frame: &mut ratatui::Frame, data: &Snapshot, state: &AppState) {
    let Some(item) = data.activity.get(state.selected) else {
        return;
    };
    let detail_width = 84usize.saturating_sub(4).max(1);
    let detail_rows = item
        .detail
        .lines()
        .map(|line| line.chars().count().div_ceil(detail_width))
        .sum::<usize>();
    let detail_height = detail_rows.saturating_add(4).clamp(7, 18) as u16;
    let area = centered(frame.area(), 84, detail_height);
    frame.render_widget(Clear, area);
    frame.render_widget(
        Paragraph::new(item.detail.as_str())
            .scroll((state.scroll, 0))
            .wrap(Wrap { trim: false })
            .block(
                Block::default()
                    .title(format!(
                        "  {} · evidence · Esc close · ↑↓ scroll  ",
                        item.title
                    ))
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(theme_accent(&data.theme)))
                    .style(Style::default().bg(SURFACE)),
            ),
        area,

fn render_help(frame: &mut ratatui::Frame, data: &Snapshot, state: &AppState) {
    let area = centered(frame.area(), 64, 14);
    frame.render_widget(Clear, area);
    frame.render_widget(Paragraph::new("Navigate activity   ↑/↓ or j/k\nInspect selected item   enter or d\nInspect validation   v\nScroll detail   ↑/↓\nClose detail/help   Esc\nReturn to REPL   q\n\nThe session view summarizes activity. Full tool output remains available in each evidence view.").scroll((state.scroll, 0)).wrap(Wrap { trim: false }).block(Block::default().title("  NEXUS KEYS  ").borders(Borders::ALL).border_style(Style::default().fg(theme_accent(&data.theme))).style(Style::default().bg(SURFACE))), area);
}

fn centered(area: Rect, width: u16, height: u16) -> Rect {
    let width = width.min(area.width.saturating_sub(4)).max(1);
    let height = height.min(area.height.saturating_sub(2)).max(1);
    Rect::new(
        area.x + (area.width - width) / 2,
        area.y + (area.height - height) / 2,
        width,
        height,
    )
}

fn one_line(value: &str, max: usize) -> String {
    let clean = value.split_whitespace().collect::<Vec<_>>().join(" ");
    let max = max.max(4);
    if clean.chars().count() <= max {
        clean
    } else {
        format!("{}…", clean.chars().take(max - 1).collect::<String>())
    }
}

fn short_path(value: &str, max: usize) -> String {
    one_line(value.rsplit('/').next().unwrap_or(value), max)
}

