/// Theme tokens for diffs at one colour depth.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Palette {
    pub add_bg: Option<Color>,
    pub del_bg: Option<Color>,
    pub add_fg: Color,
    pub del_fg: Color,
    pub number: Color,
    pub add_number: Color,
    pub del_number: Color,
    pub bar: Color,
    pub text: Color,
    pub meta: Color,
    /// Background of code blocks and command output in the transcript.
    pub code_bg: Option<Color>,
    pub syntax: Option<Syntax>,
    /// No colour at all (`NO_COLOR`, `TERM=dumb`): anything that colour would carry needs a glyph or a label.
    pub mono: bool,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Syntax {
    pub keyword: Color,
    pub string: Color,
    pub comment: Color,
    pub number: Color,
    pub type_name: Color,
}

impl Syntax {
    fn color(&self, token: Token, text: Color) -> Color {
        match token {
            Token::Plain => text,
            Token::Keyword => self.keyword,
            Token::Str => self.string,
            Token::Comment => self.comment,
            Token::Number => self.number,
            Token::Type => self.type_name,
        }
    }
}

/// The diff palette follows the terminal's configured foreground and background at every colour depth. Semantic
/// ANSI colors provide accents without assuming a dark canvas; `+` and `−` markers carry the meaning as well.
pub fn palette(depth: Depth) -> Palette {
    let mono = depth == Depth::Mono;
    Palette {
        add_bg: None,
        del_bg: None,
        add_fg: if mono { Color::Reset } else { Color::Green },
        del_fg: if mono { Color::Reset } else { Color::Red },
        number: Color::Reset,
        add_number: if mono { Color::Reset } else { Color::Green },
        del_number: if mono { Color::Reset } else { Color::Red },
        bar: Color::Reset,
        text: Color::Reset,
        meta: Color::Reset,
        code_bg: None,
        mono,
        syntax: (!mono).then_some(Syntax {
            keyword: Color::Magenta,
            string: Color::Yellow,
            comment: Color::Reset,
            number: Color::LightYellow,
            type_name: Color::Cyan,
        }),
    }
}

